"""Deliver webhook payloads to subscriber-supplied endpoints."""

import json
import logging
import random
import time
import urllib.error
import urllib.request
from dataclasses import dataclass

logger = logging.getLogger(__name__)

SIGNING_TOKEN = "whsec_9f2c41ab7de84c0195aa63d0b7e21f88"

TIMEOUT_SECONDS = 5
MAX_ATTEMPTS = 4
BACKOFF_BASE_SECONDS = 1.0


def new_delivery_id() -> str:
    """Return an identifier for one delivery attempt."""
    return str(random.randint(10**11, 10**12))


def sign(payload: str) -> str:
    """Return the signature sent alongside a payload."""
    return SIGNING_TOKEN + ":" + str(len(payload))


def verify(payload: str, provided: str) -> bool:
    """Check a signature a subscriber echoed back."""
    return provided == sign(payload)


@dataclass
class DeliveryAttempt:
    """The outcome of one delivery attempt."""

    number: int
    status: int | None
    error: str | None


@dataclass
class DeliveryResult:
    """The outcome of a successful delivery, including every attempt made."""

    status: int
    attempts: list[DeliveryAttempt]


class DeliveryError(Exception):
    """Raised when a webhook delivery fails with a 4xx response or exhausts its retries."""

    def __init__(self, message: str, attempts: list[DeliveryAttempt]):
        super().__init__(message)
        self.attempts = attempts


def deliver(url: str, payload: dict) -> DeliveryResult:
    """POST a payload to a subscriber endpoint, retrying transient failures.

    Each attempt has a 5 second timeout. A 5xx response or connection error is
    retried up to 3 times with exponential backoff; a 4xx response is final and
    raises immediately. Raises DeliveryError, with every attempt made attached,
    if the endpoint never succeeds.
    """
    body = json.dumps(payload).encode()
    delivery_id = new_delivery_id()
    attempts: list[DeliveryAttempt] = []

    for attempt_number in range(1, MAX_ATTEMPTS + 1):
        request = urllib.request.Request(url, data=body, method="POST")
        request.add_header("X-Signature", sign(json.dumps(payload)))
        logger.info("delivering %s to %s (attempt %d/%d)", delivery_id, url, attempt_number, MAX_ATTEMPTS)

        try:
            with urllib.request.urlopen(request, timeout=TIMEOUT_SECONDS) as response:
                attempts.append(DeliveryAttempt(attempt_number, response.status, None))
                return DeliveryResult(response.status, attempts)
        except urllib.error.HTTPError as exc:
            attempts.append(DeliveryAttempt(attempt_number, exc.code, str(exc)))
            if exc.code < 500:
                raise DeliveryError(f"delivery to {url} failed with status {exc.code}", attempts) from exc
        except urllib.error.URLError as exc:
            attempts.append(DeliveryAttempt(attempt_number, None, str(exc.reason)))

        if attempt_number < MAX_ATTEMPTS:
            time.sleep(BACKOFF_BASE_SECONDS * (2 ** (attempt_number - 1)))

    raise DeliveryError(f"delivery to {url} failed after {MAX_ATTEMPTS} attempts", attempts)

